const body = $input.first().json;
const tweets = Array.isArray(body.tweets) ? body.tweets : [];
const normalized = tweets.map((tweet) => {
  const id = tweet.id ?? '';
  const author = tweet.author ?? {};
  return {
    id,
    url: tweet.url ?? (id ? `https://x.com/i/web/status/${id}` : ''),
    text: tweet.text ?? '',
    author: author.username ?? author.name ?? '',
    created_at: tweet.createdAt ?? null,
    metrics: {
      like_count: tweet.likeCount ?? null,
      reply_count: tweet.replyCount ?? null,
      retweet_count: tweet.retweetCount ?? null,
      quote_count: tweet.quoteCount ?? null,
      view_count: tweet.viewCount ?? null,
      bookmark_count: tweet.bookmarkCount ?? null
    }
  };
});
const digestLines = normalized.length === 0
  ? ['No matching X posts found for this query.']
  : normalized.map((tweet, index) => {
      const author = tweet.author ? ` by ${tweet.author}` : '';
      const link = tweet.url ? `\n${tweet.url}` : '';
      return `${index + 1}. ${tweet.text}${author}${link}`;
    });
return [{
  json: {
    query: $('Search Settings').first().json.query,
    results_count: normalized.length,
    has_next_page: body.has_next_page === true,
    next_cursor: typeof body.next_cursor === 'string' ? body.next_cursor : '',
    tweets: normalized,
    digest: digestLines.join('\n\n')
  }
}];
